const { Client, SlashCommandBuilder } = require('discord.js');

const client = new Client({ intents: ['Guilds', 'GuildMessages'] });

const banCommand = new SlashCommandBuilder()
  .setName('ban')
  .setDescription('Bans a user from the server')
  .addUserOption((option) =>
    option
      .setName('user')
      .setDescription('The user to ban')
      .setRequired(true)
  );

client.commands = [];

client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}!`);

  client.commands.push(banCommand);
});

client.on('interactionCreate', async (interaction) => {
  if (!interaction.isCommand()) return;

  const { commandName, options } = interaction;

  if (commandName === 'ban') {
    const user = options.getUser('user');

    if (!user) {
      return interaction.reply({
        content: 'Please provide a user to ban.',
        ephemeral: true,
      });
    }

    await interaction.guild.members.ban(user, { reason: 'Banned by Discord bot' });

    interaction.reply({
      content: `User ${user.tag} has been banned.`,
      ephemeral: true,
    });
  }
});

client.login('YOUR_DISCORD_BOT_TOKEN_HERE');
```

