std::string markdownToHtml(const std::string& markdown) {
    // Define a regular expression pattern to match Markdown syntax
    const std::regex markdownRegex{
        R"(^|\n)(?:\*\*([^\*\n]+?)\*\*)"                                 // Bold text
        "|\\[([^\\]]+?\\)]"                                               // Links
        "|_([^\\n_]+?)_"                                                  // Italic text
