        {"\\[\\s*([^\\n\\]]+?)\\s*\\]", "<li><strike>$1</strike></li>"},
        {"\\s+|\\n+", "<br/>"}
    };

    // Define a stream to hold the resulting HTML
    std::ostringstream htmlStream;

    // Iterate over each match in the Markdown string
    std::smatch match;
    while (std::regex_search(markdown, match, markdownRegex)) {
